import{_ as o,a0 as p,w as d,s as r,ao as n,I as t,x as e,a1 as i,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"命令别名：定义自己的命令 | LCTT x X-CMD","titleTemplate":false,"description":"命令别名：定义自己的命令 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令别名：定义自己的命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令别名：定义自己的命令 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181212 Aliases- DIY Shell Commands","title":"命令别名：定义自己的命令","tag":"201812","desc":""},"relativePath":"201812/20181212 Aliases- DIY Shell Commands.md","filePath":"[post].md"}'),c={name:"201812/20181212 Aliases- DIY Shell Commands.md"};function u(h,s,g,k,b,f){const a=p("Link");return d(),r("div",null,[s[25]||(s[25]=n('<h1 id="命令别名-定义自己的命令" tabindex="-1">命令别名：定义自己的命令 <a class="header-anchor" href="#命令别名-定义自己的命令" aria-label="Permalink to “命令别名：定义自己的命令”">​</a></h1><blockquote><p>学习如何创建别名：你可以将太长或难以记忆的命令打包成你自己构建的命令。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/jodi-mucha-540841-unsplash.jpg?itok=n1d1VDUV" alt=""></p><p><ruby>命令别名<rt>Alias</rt></ruby>在 Linux shell 中指的是将一些太长或者太难记的多个命令组合起来，成为一个由用户自己构建的命令。</p><p>可以通过 <code>alias</code> 命令来创建命令别名。在 <code>alias</code> 后面跟上想要创建的别名名称、一个等号（<code>=</code>），以及希望使用这个别名来执行的命令，这样一个命令别名就创建好了。举个例子，<code>ls</code> 命令在默认情况下是不会对输出的内容进行着色的，这样就不能让用户一眼分辨出目录、文件和连接了。对此，可以创建这样一个命令别名，在输出目录内容的时候为输出内容着色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lc=&#39;ls --color=auto&#39;</span></span></code></pre></div><p>其中 <code>lc</code> 是自定义的命令别名，代表 “list with color” 的意思。在创建命令别名的时候，需要先确认使用的别名是不是已经有对应的命令了，如果有的话，原本的命令就会被覆盖掉了。注意，定义命令别名的时候，<code>=</code> 两端是没有空格的。当运行 <code>lc</code> 的时候，就相当于执行了 <code>ls --color</code> 命令。</p><p>此后，执行 <code>lc</code> 列出目录内容的时候，就会输出带有着色的内容了。</p><p>你可能会发现你在执行 <code>ls</code> 的时候，本来就是输出带有着色的内容。那是因为大部分 Linux 发行版都已经将 <code>ls</code> 设定为带有着色的命令别名了。</p><h3 id="可以直接使用的命令别名" tabindex="-1">可以直接使用的命令别名 <a class="header-anchor" href="#可以直接使用的命令别名" aria-label="Permalink to “可以直接使用的命令别名”">​</a></h3><p>实际上，执行不带任何内容的 <code>alias</code> 命令就可以看到当前已经设定的所有命令别名。对于不同的发行版，包含的命令别名不尽相同，但普遍都会有以下这些命令别名：</p><ul><li><code>alias ls=&#39;ls --color=auto&#39;</code>：这个命令别名在前面已经提到过了。<code>--color=auto</code> 参数会让 <code>ls</code> 命令在通过标准输出在终端中显示内容时进行着色，而其它情况（例如通过管道输出到文件）下则不进行着色。<code>--color</code> 这个参数还可以设置为 <code>always</code> 或<code>never</code>。</li><li><code>alias cp=&#39;cp -i&#39;</code>：<code>-i</code> 参数代表“<ruby>交互<rt>interactive</rt></ruby>”。在使用 <code>cp</code> 命令复制文件的时候，可能会无意中覆盖现有的文件，在使用了 <code>-i</code> 参数之后，<code>cp</code> 命令会在一些关键操作前向用户发出询问。</li><li><code>alias free=&#39;free -m&#39;</code>：在 <code>free</code> 命令后面加上 <code>-m</code> 参数，就可以将输出的内存信息以 MiB 这个更方面阅读和计算的单位输出，而不是默认的 Byte 单位。</li></ul><p>你使用的发行版自带的命令别名可能多多少少和上面有些差别。但你都可以在命令前面加上 <code>\\</code> 修饰符来使用命令的最基本形式（而不是别名）。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\free</span></span></code></pre></div><p>就是直接执行 <code>free</code>，而不是 <code>free -m</code>。还有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\ls</span></span></code></pre></div><p>执行的就是不带有<code>--color=auto</code> 参数的 <code>ls</code>。</p>',17)),t("p",null,[s[1]||(s[1]=e("如果想要持久地保存命令别名，可以在 ",-1)),s[2]||(s[2]=t("code",null,".bashrc",-1)),s[3]||(s[3]=e(" 文件中进行修改，而它",-1)),i(a,{href:"https://linux.cn/article-10370-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("来源于我们的 /etc/skel 目录",-1)])]),_:1}),s[4]||(s[4]=e("。",-1))]),s[26]||(s[26]=n(`<h3 id="使用命令别名纠正错误" tabindex="-1">使用命令别名纠正错误 <a class="header-anchor" href="#使用命令别名纠正错误" aria-label="Permalink to “使用命令别名纠正错误”">​</a></h3><p>各种发行版的设计者都会尽量设置用户可能需要用到的命令别名。但是不同的用户的习惯各不相同，一些用户可能刚从其它操作系统迁移到 Linux，而不同操作系统的基本命令又因 shell 而异。因此，对于刚从 Windows/MS-DOS 系统迁移到 Linux 系统的用户，不妨使用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias dir=&#39;ls&#39;</span></span></code></pre></div><p>这个命令别名来列出目录内容。</p><p>类似地，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias copy=&#39;cp&#39;</span></span>
<span class="line"><span>alias move=&#39;mv&#39;</span></span></code></pre></div><p>也可以在尚未完全熟悉 Linux 的时候用得顺手。</p><p>还有一种情况，就是在经常出现输入错误的场合中做出容错，例如，对于我来说， Administration 这个单词就很难快速正确地输入，因此很多用户都会设置类似这样的别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias sl=&#39;ls&#39;</span></span></code></pre></div><p>以及</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias gerp=&#39;echo &quot;You did it *again*!&quot;; grep&#39;</span></span></code></pre></div><p><code>grep</code> 命令最基本的用途就是在文件中查找字符串，在熟悉这个命令之后，它一定是最常用的命令之一，因此输入错误导致不得不重输命令就很令人抓狂。</p><p>在上面 <code>gerp</code> 的例子中，包含的不只是一条命令，而是两条。第一条命令 <code>echo &quot;You did it *again*!&quot;</code> 输出了一条提醒用户拼写错误的消息，然后使用分号（<code>；</code>）把两条命令隔开，再往后才是 <code>grep</code> 这一条正确的命令。</p><p>在我的系统上使用 <code>gerp</code> 来搜索 <code>/etc/skel/.bashrc</code> 中包含“alias”这个单词的行，就会输出以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gerp -R alias /etc/skel/.bashrc</span></span>
<span class="line"><span>You did it *again*! </span></span>
<span class="line"><span>       alias ls=&#39;ls --color=auto&#39; </span></span>
<span class="line"><span>       alias grep=&#39;grep --colour=auto&#39; </span></span>
<span class="line"><span>       alias egrep=&#39;egrep --colour=auto&#39; </span></span>
<span class="line"><span>       alias fgrep=&#39;fgrep --colour=auto&#39; </span></span>
<span class="line"><span>alias cp=&quot;cp -i&quot;</span></span>
<span class="line"><span>alias df=&#39;df -h&#39;</span></span>
<span class="line"><span>alias free=&#39;free -m&#39;</span></span>
<span class="line"><span>alias np=&#39;nano -w PKGBUILD&#39; </span></span>
<span class="line"><span>alias more=less </span></span>
<span class="line"><span>shopt -s expand_aliases</span></span></code></pre></div><p>在命令别名中以固定的顺序执行多个命令，甚至更进一步，把多个命令串连起来，让后面的命令可以使用到前面的命令的执行结果。这样的做法已经非常接近 bash 脚本了。这篇文章已经接近尾声，我们将在下一篇文章中详细介绍。</p><p>如果想要删除在终端中临时设置的别名，可以使用 <code>unalias</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unalias gerp</span></span></code></pre></div>`,18)),t("p",null,[s[6]||(s[6]=e("如果想要持久保存命令别名，可以将命令别名放在用户主目录的 ",-1)),s[7]||(s[7]=t("code",null,".bashrc",-1)),s[8]||(s[8]=e(" 文件中，具体的方法在",-1)),i(a,{href:"https://linux.cn/article-10374-1.html"},{default:l(()=>[...s[5]||(s[5]=[e("上一篇文章",-1)])]),_:1}),s[9]||(s[9]=e("中已经介绍过。",-1))]),s[27]||(s[27]=t("hr",null,null,-1)),t("p",null,[s[11]||(s[11]=e("via: ",-1)),i(a,{href:"https://www.linux.com/blog/learn/2018/12/aliases-diy-shell-commands"},{default:l(()=>[...s[10]||(s[10]=[e("https://www.linux.com/blog/learn/2018/12/aliases-diy-shell-commands",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=e("作者：",-1)),i(a,{href:"https://www.linux.com/users/bro66"},{default:l(()=>[...s[12]||(s[12]=[e("Paul Brown",-1)])]),_:1}),s[17]||(s[17]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[13]||(s[13]=[e("lujun9972",-1)])]),_:1}),s[18]||(s[18]=e(" 译者：",-1)),i(a,{href:"https://github.com/HankChow"},{default:l(()=>[...s[14]||(s[14]=[e("HankChow",-1)])]),_:1}),s[19]||(s[19]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[15]||(s[15]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[e("LCTT",-1)])]),_:1}),s[23]||(s[23]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[e("Linux中国",-1)])]),_:1}),s[24]||(s[24]=e(" 荣誉推出",-1))])])}co